int main(int argc,char**argv){if(argc!=2)return 2;occ::handle<TDocStd_Document>d=new TDocStd_Document(TCollection_ExtendedString("BinXCAF"));auto t=XCAFDoc_DocumentTool::ShapeTool(d->Main());auto part=t->AddShape(BRepPrimAPI_MakeBox(2,3,4).Shape(),false);auto group=t->NewShape();auto branch=t->NewShape();auto root=t->NewShape();TDataStd_Name::Set(part,TCollection_ExtendedString("Exact planar part"));TDataStd_Name::Set(root,TCollection_ExtendedString("DAG planar NAUO assembly"));gp_Trsf a;a.SetTranslation(gp_Vec(10,0,0));auto first=t->AddComponent(group,part,TopLoc_Location(a));TDataStd_Name::Set(first,TCollection_ExtendedString("Translated use"));gp_Trsf b;b.SetValues(0,0,1,0,1,0,0,20,0,1,0,0);auto second=t->AddComponent(group,part,TopLoc_Location(b));TDataStd_Name::Set(second,TCollection_ExtendedString("Cyclic use"));auto other=t->AddShape(BRepPrimAPI_MakeBox(1,2,3).Shape(),false);TDataStd_Name::Set(other,TCollection_ExtendedString("Small independent part"));gp_Trsf c;c.SetTranslation(gp_Vec(-10,-5,7));auto third=t->AddComponent(group,other,TopLoc_Location(c));TDataStd_Name::Set(third,TCollection_ExtendedString("Independent use"));TDataStd_Name::Set(group,TCollection_ExtendedString("Shared intermediate group"));gp_Trsf outer1;outer1.SetTranslation(gp_Vec(100,0,0));auto use1=t->AddComponent(root,group,TopLoc_Location(outer1));TDataStd_Name::Set(use1,TCollection_ExtendedString("Translated group"));gp_Trsf outer2;outer2.SetValues(0,0,1,0,1,0,0,100,0,1,0,0);auto use2=t->AddComponent(root,branch,TopLoc_Location(outer2));TDataStd_Name::Set(use2,TCollection_ExtendedString("Cyclic group"));TDataStd_Name::Set(branch,TCollection_ExtendedString("Different intermediate group"));gp_Trsf shared;shared.SetTranslation(gp_Vec(0,50,0));auto nested=t->AddComponent(branch,group,TopLoc_Location(shared));TDataStd_Name::Set(nested,TCollection_ExtendedString("Shared inner group"));gp_Trsf small;small.SetTranslation(gp_Vec(0,0,30));auto leaf=t->AddComponent(branch,other,TopLoc_Location(small));TDataStd_Name::Set(leaf,TCollection_ExtendedString("Shared small leaf"));t->UpdateAssemblies();STEPCAFControl_Writer w;if(!w.Transfer(d)||w.Write(argv[1])!=IFSelect_RetDone)return 3;}
